<span class="line"><span style="color:#ABB2BF;">|</span><span style="color:#D19A66;">2025</span><span style="color:#ABB2BF;">-</span><span style="color:#D19A66;">01</span><span style="color:#ABB2BF;">-01T00:</span><span style="color:#D19A66;">06</span><span style="color:#ABB2BF;">:</span><span style="color:#D19A66;">00</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">000</span><span style="color:#ABB2BF;">+</span><span style="color:#D19A66;">08</span><span style="color:#ABB2BF;">:</span><span style="color:#D19A66;">00</span><span style="color:#ABB2BF;">|    </span><span style="color:#D19A66;">3</span><span style="color:#ABB2BF;">|   </span><span style="color:#D19A66;">80</span><span style="color:#ABB2BF;">|              L|    A|</span></span>
